# -*- coding: utf-8 -*-
"""Рядки 5226, 5227, 5234, 5887, 5946: «неперевірене» картки над справжнім судом (`від_моделі`) образів рук 1–2 файла власника
1551 (вхід — як `колір_кадр_слово_5223.py`). Пункти картки — `пункти` (ДО їх нема — `питання`), без `для_всіх`. Лічить:
речі «можливо нейтраль» (вікно слова, `_нейтраль_межі` «невідомо») у пунктах «дві нейтралі»/«нейтраль біля обличчя»;
найбільше пунктів на одну річ без виміру кольору; дублі правила (два пункти одного правила; правило·річ у двох пунктах);
пункти із заявою про речі образу без жодного `item_id` (5946: і R-FEED-01, K-COL-01 структура світлоти); питань і правил у звіті власника (`питання`). Запуск із джерела/:
python3 -W ignore проби/неперевірене_колір_5226.py ../аудит/тести/власник_2026-10-14/verdykty-0phxvk-2026-10-14-1551.json"""
import json, os, sys, collections
sys.path.insert(0, os.getcwd()); import bridge as B, колір_нейтралі as КН
д = json.load(open(sys.argv[1], encoding="utf-8")); вп = д["спільне"]["вхід_прогону"]; вх = json.load(open("стенд_вх.json"))
вх.update(зріст=вп["мірки"]["зріст"], обхвати=вп["мірки"]["обхвати"], шкіра=вп["колір"]["шкіра"][0], волосся=вп["колір"]["волосся"],
          очі=вп["колір"]["очі"], сценарій=вп["сценарій"], паспорт=д["спільне"]["паспорт"], драп=вп["драп"], випадок="x",
          каталог=os.path.abspath("каталог_повний.xml"), схема="тональна",
          вибір_кольору={"база": д["спільне"]["пал_база"], "база_hex": "#d2dbc1", "база_тип": "колір"},
          самозвіт={"барви": д["спільне"].get("самозвіт_барви"), "метал": вп["драп"].get("метал")})
B.виклик("запити", json.dumps(вх, ensure_ascii=False)); за_ід = {r["id"]: r for r in B.каталог_останнього_пакета()}
образи = [о["ід"] for в in д["прогони"][0]["вердикти"] if str(в["рука"]) in "12" for c in в["етапи"]["виклики"]
          if c.get("крок") == "assembly" for о in (c.get("образи_кроку") or [])]
НЕЙТР = {"cannot_tell_two_neutrals_distinct", "cannot_tell_neutral_near_face_temperature"}
СЛОВО = {"colour_word_shop", "colour_word_shop_photo_other", "colour_word_model", "colour_word_not_photo"}
ПРО_РЕЧІ = НЕЙТР | СЛОВО | {"cannot_tell_item_is_neutral", "cut_not_declared_assumed_regular", "cannot_tell_two_different_whites",
            "photo_shows_other_colour", "cannot_tell_lightness_structure"}
Л, найб, правил = collections.Counter(), 0, 0
for ід in образи:
    р = json.loads(B.виклик("від_моделі", json.dumps(dict(вх, ід=[і for і in ід if і in за_ід]), ensure_ascii=False)))
    пп = [п for п in (р.get("пункти") or р.get("питання") or []) if not п.get("для_всіх")]
    коди = lambda п: {з.get("code") for з in (п.get("повідомлення") or {}).get("statements") or []}
    речі = lambda п: [x for і in п.get("речі") or [] for x in str(і).split(" + ")]
    Л["пунктів картки"] += len(пп); Л["питань у звіті"] += len(р.get("питання") or []); правил += len({п.get("правило") for п in р.get("питання") or []})
    Л["«можливо нейтраль» у «дві нейтралі»/«біля обличчя»"] += sum(КН._нейтраль_межі(за_ід.get(і) or {}) == "невідомо" for п in пп if коди(п) & НЕЙТР for і in речі(п))
    на_річ = collections.Counter(і for п in пп if коди(п) & СЛОВО for і in речі(п)); найб = max([найб] + list(на_річ.values()))
    за_правилом = collections.Counter(п.get("правило") for п in пп if not (коди(п) & СЛОВО and len(речі(п)) == 1))
    Л["дублів правила (пунктів одного правила)"] += sum(к - 1 for к in за_правилом.values())
    Л["правило·річ у двох пунктах"] += sum(к > 1 for к in collections.Counter((пр, і) for п in пп for пр in set(п.get("правила") or [п.get("правило")]) for і in set(речі(п))).values())
    Л["пунктів про речі без item_id"] += sum(bool(коди(п) & ПРО_РЕЧІ) and "item_id" not in json.dumps(п.get("повідомлення")) for п in пп)
print("ФАКТ · образів %d · %s; найбільше пунктів на одну річ без виміру: %d; правил у звіті (Σ по образах): %d" % (len(образи), dict(Л), найб, правил))
